class FirstUnique {
    unordered_map<int, int> count;
    queue<int> candidates;

public:
    FirstUnique(vector<int>& nums) {
        for (int x : nums) {
            add(x);
        }
    }

    int showFirstUnique() {
        while (!candidates.empty() && count[candidates.front()] != 1) {
            candidates.pop();
        }
        return candidates.empty() ? -1 : candidates.front();
    }

    void add(int value) {
        if (++count[value] == 1) {
            candidates.push(value);
        }
    }
};
